begin;

with input_items as (
  select *
  from jsonb_to_recordset($seed_json$[]$seed_json$::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    aliases text[],
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.aliases, '{}'::text[]) as aliases,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  aliases = excluded.aliases,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset($seed_json$[{"id": "72762a1e-3baa-5f64-b565-82fc5a0285a7", "feature_slug": "sales-slides", "title": "25. Put Technical Detail In Appendix Unless It Supports The Sales Point", "content": "Main deck:\n\n- Buyer problem\n- System behavior\n- Outcome\n- Proof\n- Plan\n\nAppendix:\n\n- API details\n- Field names\n- Admin settings\n- Security architecture\n- Long feature inventory\n- Full implementation notes", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#25-put-technical-detail-in-appendix-unless-it-supports-the-sales-point", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "25-put-technical-detail-in-appendix-unless-it-supports-the-sales-point", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "3b2ae269c67aeb961ab00c1d820df2b2fc0ebc0a46aebc231a36b814a068e5ab", "truncated": false}, "is_active": true}, {"id": "c1f023c6-bc83-5133-9e64-159e5bea11dc", "feature_slug": "sales-slides", "title": "26. End With A Plan, Not \"Questions?\"", "content": "The closing slide should reduce uncertainty.\n\nUse a simple plan:\n\n> 1. Demo loyalty workflows  \n> 2. Configure member, points, and rewards logic  \n> 3. Launch first campaign in 2 weeks", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#26-end-with-a-plan-not-questions", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "26-end-with-a-plan-not-questions", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "977b8dbc295ab46b590853a9995c00124c232f9fb0fef3ba5dbc47734b946d5d", "truncated": false}, "is_active": true}, {"id": "c96a9a5b-24d7-5a5d-8bdd-88e8348ae5cf", "feature_slug": "sales-slides", "title": "27. Make The CTA Specific", "content": "Weak:\n\n> Let us know if interested.\n\nStrong:\n\n> Book a 45-minute Loyalty CRM workflow demo with your marketing and CRM team.\n\nBest CTA format:\n\n> Action + audience + timing / outcome", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#27-make-the-cta-specific", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "27-make-the-cta-specific", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "c29b14e705b058e3296c8541f803e346d31d4bac2cd5511b5ac19213d5e132c4", "truncated": false}, "is_active": true}, {"id": "567fdc37-4c53-5581-ba75-f6e5aa935997", "feature_slug": "sales-slides", "title": "3. Follow A Decision Story", "content": "A sales deck should mirror how a B2B buyer decides:\n\n1. Market shift\n2. Current problem\n3. Cost of doing nothing\n4. Better approach\n5. Rocket solution\n6. How it works\n7. Proof\n8. Implementation path\n9. Risks / objections\n10. Specific next step\n\nFor shorter decks, compress this into:\n\n> Problem → Cost → Solution → Proof → Plan → Next Step", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#3-follow-a-decision-story", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "3-follow-a-decision-story", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "50a6a5e192038163daa55c60f41e9703d48d1e8f57cf69d2a3a78b17d697e9da", "truncated": false}, "is_active": true}, {"id": "57434a2f-6a44-51bf-aee4-e3821c38acd1", "feature_slug": "sales-slides", "title": "4. Choose The Headline Type By Slide Role", "content": "Slide titles should make the slide immediately scannable. Do not force every headline into a conclusion or action-title format. Product and marketing buyers often prefer short evidence labels, feature labels, or journey labels when those are clearer than a sentence.\n\nUse the headline style that matches the slide role:\n\n- Proof / traction slides: preserve the evidence in a short label. Do not invent a broad market conclusion from a screenshot, event photo, or report image.\n- Feature-library slides: use the feature name or product category when that is clearest.\n- Journey / demo slides: use a concise journey label, not an abstract operating principle.\n- Section slides: name the category and buyer problem.\n- Company slides: position Rocket plainly; avoid PR phrases.\n\nClarity beats cleverness. If a headline names only an outcome, metric, or benefit but hides what the feature actually is, add the feature category in plain language or use the feature category as the headline. A buyer should know what they are looking at within five seconds.\n\nFor feature-library slides, the feature name itself is often the clearest headline. High-intent buyers already know they are checking whether Rocket has `Rewards`, `Tiers`, `Missions`, `Referrals`, `Dashboard`, or `Workflow`. Do not force a \"sexy\" benefit headline if it becomes abstract. Use the feature name as the header, then make the body prove scope, behavior, and buyer value.\n\nWeak:\n\n> Omnichannel Loyalty\n\nToo abstract:\n\n> Every purchase channel should build the same customer profile.\n\nStronger:\n\n> Omnichannel Point Collection\n\nAlso acceptable:\n\n> Purchase to Profile to Reward\n\nWeak proof headline:\n\n> Rocket brings the Loyalty CRM conversation to the market.\n\nStronger proof headlines:\n\n> Leading innovation in Thailand\n\n> Most likely to choose CRM in 2025\n\n> Top B2C CRM consideration set\n\nWeak:\n\n> Increase ROI by 30% with always-on automation.\n\nStronger:\n\n> Customer Service AI - Chat\n\nAlso acceptable:\n\n> Customer Service AI - Chat resolves common questions before they reach an agent.\n\nAlso acceptable for feature-library slides:\n\n> Rewards\n\nThen the body must answer what is configurable, what the customer sees, and what the operator controls.\n\nWeak:\n\n> AI Personalization\n\nStrong:\n\n> AI turns customer data into the next best action automatically.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#4-choose-the-headline-type-by-slide-role", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "4-choose-the-headline-type-by-slide-role", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "d0e0112361672fa28f9e30ca6f9865d4bde1905828115e8d288f7c10182a3dbd", "truncated": false}, "is_active": true}, {"id": "11133bfe-2ba2-51b0-b79d-e56922806a55", "feature_slug": "sales-slides", "title": "5. One Main Message Per Slide", "content": "Each slide needs one governing thought. Supporting text, diagrams, screenshots, and numbers must all support that thought.\n\nIf a slide has two conclusions, split it.\n\nWrite the slide as one composed artifact, not as independent text fields. Before changing copy, read the title, body, labels, diagram, screenshot, and callouts together. Decide what the visual already proves, then make the text add the missing business meaning.\n\nRules:\n\n- The headline should frame the slide's concept or decision point.\n- Body copy should explain why the visual matters, not narrate what the audience can already see.\n- Labels should help scanning; they should not become a second paragraph broken into fragments.\n- Do not fill feature slides with every possible product keyword. Choose the altitude the slide needs: concept, model, workflow, feature scope, or implementation detail.\n\nExamples:\n\n- A campaign → Customer 360 → activation timeline should not be titled with a narrow tactic like \"Campaigns should trigger the next best action.\" If the visual is showing the ideal customer loop, use the concept: `Perfect retention journey`.\n- A rule-engine diagram should not dump every possible action, condition, and outcome. Explain the concept at the right altitude: `Trigger → Decision → Result`.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#5-one-main-message-per-slide", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "5-one-main-message-per-slide", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "5e5434aff27042743f23ab8416a44b05f06d0ec636a7bde12ce404091398ce8c", "truncated": false}, "is_active": true}, {"id": "29b188d7-e97d-5271-97fe-c67ebfee0d03", "feature_slug": "sales-slides", "title": "6. Translate Thai Slides For Understanding, Not Literal Purity", "content": "When writing Thai slide content, keep technical product terms in English when there is no natural Thai equivalent or when the English term is the market-standard phrase.\n\nKeep terms like:\n\n- `Omnichannel`\n- `Customer Service AI`\n- `Chat`\n- `CRM`\n- `Dashboard`\n- `Workflow`\n- `Segment`\n- `Campaign`\n\nTranslate the surrounding explanation into natural Thai, but do not force awkward Thai replacements for technical words. Define the term once if needed, then use it consistently.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#6-translate-thai-slides-for-understanding-not-literal-purity", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "6-translate-thai-slides-for-understanding-not-literal-purity", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "67b852daeb3b55a2ac68f1978c5f0c888d025c7032d156ec4796b64f8854f744", "truncated": false}, "is_active": true}, {"id": "bc7b643d-6947-5f7b-ba33-63a2706dce89", "feature_slug": "sales-slides", "title": "7. Use Core Structure At Deck, Section, And Slide Level", "content": "Apply `CORE_WRITING_PRINCIPLES.md` to every deck:\n\n- Pyramid structure: the deck, section, and slide each need a core concept.\n- Vertical logic: every supporting point must serve the slide's main message.\n- Horizontal logic: peer items should be grouped by one dimension.\n- MECE: sections and slide groups should avoid overlaps and obvious gaps.\n- Same-level abstraction: flat lists should not mix category, feature, channel, outcome, and UI detail.\n\nGood Rocket section grouping:\n\n> Convert → Engage → Activate\n\nEach stage has a clear role:\n\n- Convert: registration, points, unified profile, omnichannel collection.\n- Engage: tiers, rewards, missions, referrals, gamified campaigns.\n- Activate: segmentation, churn prediction, personalized offers, automated campaigns.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#7-use-core-structure-at-deck-section-and-slide-level", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "7-use-core-structure-at-deck-section-and-slide-level", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "f2d1d9f5eca1d22e715604ee68b737f6383d3c2f6a4fad87228fe5ad28acb172", "truncated": false}, "is_active": true}, {"id": "74e75d92-7526-56d4-9bce-ed91904127b8", "feature_slug": "sales-slides", "title": "8. Same-Level Discipline Applies To Peer Items On Slides", "content": "Do not mix abstraction levels inside a flat slide list.\n\nBad:\n\n> Loyalty CRM / Points / AI / LINE / Increase retention / Dashboard\n\nThis mixes category, feature, technology, channel, outcome, and interface.\n\nGood, grouped by capability:\n\n> Points / Tiers / Rewards / Missions / Referrals\n\nGood, grouped by outcome:\n\n> Convert customers / Engage members / Activate data\n\nGood, grouped by channel:\n\n> POS / Online Store / Marketplace / Receipt Upload / QR Scan", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#8-same-level-discipline-applies-to-peer-items-on-slides", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "8-same-level-discipline-applies-to-peer-items-on-slides", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "f90e7572a29c18bf39422b291f5dfae6dbec644045e29534a3ecb5ac4dd2afda", "truncated": false}, "is_active": true}, {"id": "6238a502-8a83-512e-a7b6-a3b28d2bc664", "feature_slug": "sales-slides", "title": "9. Visual Structures May Mix Levels If The Relationship Is Explicit", "content": "Overview, journey, and system-flow slides can mix levels because their job is to show how things connect.\n\nAllowed:\n\n- Overview map: `Convert → Engage → Activate`, with example features under each stage.\n- Journey flow: `Customer buys on Shopee → claims points → joins tier → gets AI offer`.\n- System diagram: `Purchase channel → Loyalty engine → Customer profile → AMP workflow → LINE message`.\n- Opening slide: one market shift, one category anchor, one proof point.\n\nThe rule:\n\n> Do not mix levels in a flat list. You may mix levels in a hierarchy, journey, matrix, or system diagram when the layout makes the relationship obvious.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#9-visual-structures-may-mix-levels-if-the-relationship-is-explicit", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "9-visual-structures-may-mix-levels-if-the-relationship-is-explicit", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "5f3ef70b0d91d3f826521cea153700309ddec6a81807588fc997e601196172c8", "truncated": false}, "is_active": true}, {"id": "c1007cd3-a0a2-54ef-ab1d-7ee1292cf1b7", "feature_slug": "sales-slides", "title": "Core Narrative", "content": "Use this as the default Rocket loyalty sales story:\n\n1. Customer expectations changed: customers expect brands to know them, reward them, and personalize the relationship.\n2. Most loyalty programs stop too early: points and rewards create members, but not necessarily active customers.\n3. Marketing teams need a system that moves through three stages:\n   - Convert: turn customers into known members and collect first-party data.\n   - Engage: give members reasons to interact beyond purchase.\n   - Activate: use data and AI to take the right action for each customer.\n4. Rocket is the Loyalty CRM that connects those stages in one customer profile and one action system.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#core-narrative", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "core-narrative", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "d6a11354a3f96c16167aa5ae406c165949c0580e8a47791208ccc34294a11b70", "truncated": false}, "is_active": true}, {"id": "5bcee532-a152-5e44-b349-01d2fc4d12b0", "feature_slug": "sales-slides", "title": "Purpose", "content": "These principles guide Rocket sales presentation slides for B2B SaaS buyers, especially marketing teams evaluating Loyalty CRM and loyalty program platforms.\n\nThe goal is not a prettier feature tour. The goal is a buyer-ready decision story: clear in the meeting, structured enough for the champion to forward internally, and specific enough that marketing, finance, IT, and leadership can understand why Rocket is the right system.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#purpose", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "purpose", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "fb04d7f2aa77981c24ac9c7e2d7e7a3d295f0d9d9c38679d12959aa9312e4c51", "truncated": false}, "is_active": true}, {"id": "b83cc540-4fba-5645-96af-35e99da81db1", "feature_slug": "sales-slides", "title": "Quality Checklist", "content": "- Does the cover pass the 5-second test: what is it, and who is it for?\n- Is the deck written from the buyer's point of view?\n- Does the structure follow a clear decision story?\n- Does each slide have one conclusion?\n- Does the copy compound with the visual instead of describing it?\n- Do feature headlines make the product category clear? If the benefit headline is vague, use the feature name.\n- Can someone understand the argument from slide titles alone?\n- Do feature slides pass the 5-second test: what feature is this, and why should this stakeholder care?\n- Do broad feature claims include concrete checklist items at the same abstraction level?\n- Do Thai slides keep market-standard technical terms in English when Thai translation would be awkward or less clear?\n- Are peer lists at the same abstraction level?\n- Are overview and journey slides using hierarchy or flow, not random mixed lists?\n- Is the core Rocket story clear: Convert → Engage → Activate?\n- Are AI claims described through specific decisions and actions?\n- Is proof placed before heavy feature detail?\n- Are objections handled directly?\n- Is the next step specific enough to put on a calendar?", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#quality-checklist", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "quality-checklist", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "13daf3c8d1194c7ecfb57c962e56d1d1befdddbcadd57bc2972049bda1034402", "truncated": false}, "is_active": true}, {"id": "09066311-3fc2-5542-9038-f4d1e2cfaa2a", "feature_slug": "sales-slides", "title": "Sales Presentation Slides — Overview", "content": "**When to use:** Sales decks, marketing presentations, buyer-facing slide narratives. One message per slide, decision story, proof, objections.\n**Source:** `SALES_PRESENTATION_SLIDE_PRINCIPLES.md`\n**Genre:** `slides`\n\nThese principles guide Rocket sales presentation slides for B2B SaaS buyers, especially marketing teams evaluating Loyalty CRM and loyalty program platforms.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "overview", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "f65f10cc5a526c04dc6c443698ef7059ecf76653799bcf693ee2b30f1b867559", "truncated": false}, "is_active": true}, {"id": "5b0bc014-7524-536d-857b-1922a8174f3d", "feature_slug": "sales-slides", "title": "Source Principles", "content": "This document adapts Rocket's existing content rules:\n\n- `CORE_WRITING_PRINCIPLES.md` — pyramid structure, vertical logic, horizontal logic, MECE, same-level grouping, layered depth, concrete specificity, explicit limitations.\n- `PROPOSAL_WRITING_PRINCIPLES.md` — journey walkthroughs, concrete system behavior, implementation trade-offs, systems architect voice.\n- `WEB_PAGE_COPY_PRINCIPLES.md` (Part 1 — Landing Page Copy) — 5-second clarity, customer-as-hero, punchy headlines, proof before features, objection handling, short CTAs.\n- `ROCKET_PRODUCT_MESSAGING.md` — Loyalty CRM positioning, Convert → Engage → Activate, AI as activation rather than analysis.\n- `platform-overview.md` — omnichannel points, unified customer profile, tiers, rewards, missions, referrals, AMP workflows, AI decisioning.\n\nExternal references:\n\n- April Dunford's sales pitch / positioning framework: market insight → alternatives → differentiated value → proof → ask.\n- Gong sales presentation research: context before demo, business value over features, surface objections early.\n- think-cell and SlideModel on Pyramid Principle and MECE for PowerPoint: conclusion-first structure, hierarchy, no gaps, no overlaps.\n- Deckary consulting presentation guide: action titles, one message per slide, vertical and horizontal logic.\n- Sako / Proofmap B2B SaaS deck guides: problem → cost → solution → proof → next step, with process and system-flow slides for complex products.", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/SALES_PRESENTATION_SLIDE_PRINCIPLES.md#source-principles", "metadata": {"genre": "slides", "source_file": "SALES_PRESENTATION_SLIDE_PRINCIPLES.md", "section_anchor": "source-principles", "feature_slug": "sales-slides", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "01298a3c37a43613c6eff8cfd8d831044399e558e2112e6b2c166b33c4c06a7d", "truncated": false}, "is_active": true}, {"id": "b79eb606-38e8-5caa-ab2a-3d2b159bb29a", "feature_slug": "translation", "title": "AI & Technology Term Principles", "content": "These apply universally across all markets:\n\n1. **Name the decision, not the technology.** \"AI predicts which customers will stop buying and sends them a personalized offer\" — not \"AI-powered machine learning analytics engine.\"\n2. **Frame as augmentation, not replacement.** AI helps the team do more, not replaces the team. Especially important in JP and TW enterprise contexts.\n3. **Keep \"AI\" in the sentence when using analogy.** \"AI acts like your best marketing intern — but works 24/7\" keeps it grounded. Don't let the analogy erase the AI reference.\n4. **Precision over claims.** \"AI sends personalized offers to each customer automatically\" > \"cutting-edge AI technology.\" Show what it does, not what it is.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/TRANSLATION_PHILOSOPHY.md#ai-technology-term-principles", "metadata": {"genre": "translation", "source_file": "TRANSLATION_PHILOSOPHY.md", "section_anchor": "ai-technology-term-principles", "feature_slug": "translation", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "c97f70d3858c3afdcd1ee6d7cebdbfe009badada8934d3b4ead56f9decfef5f4", "truncated": false}, "is_active": true}, {"id": "80a5f9a4-2eb7-5f31-b862-f259deab8b2f", "feature_slug": "translation", "title": "Core Principle: Localize, Don't Translate", "content": "We don't swap words between languages. We rewrite each text component so it reads like it was written by a sharp marketer in that market. The test: would a native speaker in the target market assume this was originally written in their language?\n\n**What this means in practice:**\n\n| Approach | Example (JP) | Result |\n|---|---|---|\n| Translation (wrong) | \"Turn customers into members\" → \"顧客をメンバーに変える\" | Grammatically correct, sounds like a translation |\n| Localization (right) | \"Turn customers into members\" → \"顧客を会員に。全チャネルで。\" | Sounds like a Japanese marketer wrote it |\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/TRANSLATION_PHILOSOPHY.md#core-principle-localize-don-t-translate", "metadata": {"genre": "translation", "source_file": "TRANSLATION_PHILOSOPHY.md", "section_anchor": "core-principle-localize-don-t-translate", "feature_slug": "translation", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "2b26906b1fd3dd1bf2d219c04aa8cb0124e052bee153ecd4f66a48eab2d96abb", "truncated": false}, "is_active": true}, {"id": "773a0dd6-2f4a-5843-8f84-5bf55a33a264", "feature_slug": "translation", "title": "Currency & Number Formatting", "content": "Always convert to local currency and format. Never leave prices in a foreign currency.\n\n| Market | Currency | Format | Example |\n|---|---|---|---|\n| **Japan** | Yen (JPY) | ¥ prefix, no decimal, comma separator | ¥1,500 |\n| **Taiwan** | New Taiwan Dollar (TWD) | NT$ prefix, no decimal | NT$450 |\n| **Thailand** | Baht (THB) | ฿ prefix or \"บาท\" suffix | ฿500 or 500 บาท |\n| **English** | USD or contextual | $ prefix, 2 decimal places | $15.00 |\n\n**Numbers:**\n- Use local number formatting (comma/period conventions)\n- Quantities: use local counter words where natural (JP: 枚 for coupons, 人 for people; TW: 張 for coupons; TH: ใบ for coupons)\n- Percentages: use % universally\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/TRANSLATION_PHILOSOPHY.md#currency-number-formatting", "metadata": {"genre": "translation", "source_file": "TRANSLATION_PHILOSOPHY.md", "section_anchor": "currency-number-formatting", "feature_slug": "translation", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "d55441993d356aebca22f1911b525ebed087dcf8bbd74ef64786e11fabf8ebf3", "truncated": false}, "is_active": true}, {"id": "ec98f011-f8ac-5fc6-aab2-c9bfed8aef44", "feature_slug": "translation", "title": "English Term Policy", "content": "Industry-standard terms stay in English across all markets. The test: if a B2B SaaS website in the target market would use this term in English, keep it in English.\n\n**Always keep in English:**\n\n| Category | Terms |\n|---|---|\n| **Technical** | AI, CRM, Dashboard, API, SaaS, POS, EC, QR, OTP, SLA, Push Notification, Omnichannel |\n| **Metrics** | ROI, LTV, CLV, KPI, CSAT, AOV, CAC |\n| **Platform names** | LINE, Shopify, Shopee, Lazada, TikTok, WhatsApp, Facebook, Instagram |\n| **Brand names** | Rocket, Agentic CRM |\n| **Tier names** | Gold, Silver, Platinum (keep English unless market doc overrides) |\n\n**Market-specific decisions:** Some terms are borderline. The market-specific doc decides:\n- \"Omnichannel\" — English in JP/EN, localized in TH/TW\n- \"Churn\" — English in EN, localized in JP/TH/TW\n- \"Mission\" — depends on market (ミッション in JP, kept English or ภารกิจ in TH)\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/TRANSLATION_PHILOSOPHY.md#english-term-policy", "metadata": {"genre": "translation", "source_file": "TRANSLATION_PHILOSOPHY.md", "section_anchor": "english-term-policy", "feature_slug": "translation", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "13c715819c483645c8d83a171e1a65604bdbe5b2bed468dda018cee24cbfc683", "truncated": false}, "is_active": true}, {"id": "02a7a988-a6d0-5b2a-91f4-aa6a17da7f96", "feature_slug": "translation", "title": "Per-Market Context Docs", "content": "Each market has a dedicated doc that inherits these universal rules and adds:\n\n1. **Market context** — who buys, what they search for, cultural notes\n2. **Feature vocabulary table** — canonical translations for every domain-specific term\n3. **Feature nuances** — how features resonate differently in this market\n4. **UI translation patterns** — common component translations\n5. **CTA patterns** — call-to-action conventions\n\n| Market | Doc | Language |\n|---|---|---|\n| Japan | [JAPAN_CONTEXT.md](JAPAN_CONTEXT.md) | Japanese |\n| Taiwan | [TAIWAN_CONTEXT.md](TAIWAN_CONTEXT.md) | Traditional Chinese (zh-TW) |\n| Thailand | [THAILAND_CONTEXT.md](THAILAND_CONTEXT.md) | Thai |\n| English | [ENGLISH_CONTEXT.md](ENGLISH_CONTEXT.md) | English (SEA/Global) |", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/TRANSLATION_PHILOSOPHY.md#per-market-context-docs", "metadata": {"genre": "translation", "source_file": "TRANSLATION_PHILOSOPHY.md", "section_anchor": "per-market-context-docs", "feature_slug": "translation", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "26bf0a050ca63a893264cd2eb0d4bb0a8dd29569dcc405e81834a5e6d21227df", "truncated": false}, "is_active": true}, {"id": "4491cdc6-711f-5751-8b02-9a0276a3d7d6", "feature_slug": "translation", "title": "Proper Noun Rules", "content": "| Category | Rule | Examples |\n|---|---|---|\n| **Brand names** | Never translate | Rocket, LINE, Shopify, Shopee, Lazada |\n| **Product names** | Never translate | Agentic CRM |\n| **Feature names (English origin)** | Keep English if established in market | Top Spender, Dashboard, Mission (in JP) |\n| **Feature names (localized)** | Use market-specific term | 友達紹介 (JP for Referral), 會員經營 (TW for Membership Operations) |\n| **Tier names** | Keep English unless market doc overrides | Gold, Silver, Platinum |\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/TRANSLATION_PHILOSOPHY.md#proper-noun-rules", "metadata": {"genre": "translation", "source_file": "TRANSLATION_PHILOSOPHY.md", "section_anchor": "proper-noun-rules", "feature_slug": "translation", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "f6ce319c7f18ae5f81833ab4796d8a749ce47894b7a01a4944a8bacc745afea0", "truncated": false}, "is_active": true}, {"id": "71278524-ba10-5537-9a73-12144b0f0e1b", "feature_slug": "translation", "title": "Structure Fidelity", "content": "Match the original component structure. If the image shows a button, give a button-length string. If it shows a headline + subtext, give headline + subtext. Don't add or remove elements.\n\n**Rules:**\n- Button text → button-length translation (short, action-oriented)\n- Headline + subheadline → maintain the hierarchy and relative lengths\n- Feature card (title + description) → title stays punchy, description stays concise\n- Data labels → match the terseness of the original\n- If you need more words in the target language, find a shorter way to say it. Don't let translations break layouts.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/TRANSLATION_PHILOSOPHY.md#structure-fidelity", "metadata": {"genre": "translation", "source_file": "TRANSLATION_PHILOSOPHY.md", "section_anchor": "structure-fidelity", "feature_slug": "translation", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "b07f71a01753a2c3a02991be6e4049fafc13c4026141a2a0678267a29494d2ba", "truncated": false}, "is_active": true}, {"id": "bf4f7929-e952-5e4a-b6bb-7690604c60de", "feature_slug": "translation", "title": "The Complexity Spectrum", "content": "Not every text component needs the same level of effort. Calibrate by complexity:\n\n| Text type | Examples | What to do |\n|---|---|---|\n| **Simple / universal** | \"Buy Now,\" \"Gold,\" \"15 Coupons,\" \"Details →,\" \"Settings\" | Just translate. Use the natural equivalent a user expects to see. Don't overthink. |\n| **Domain-specific** | \"Tier,\" \"Omnichannel,\" \"Churn,\" \"Segment,\" \"AI Agent,\" \"Double Points\" | Check the vocabulary table in the market-specific doc. These terms have established translations — use them consistently. |\n| **Marketing copy** | Headlines, subheadlines, feature descriptions, taglines | Use the product context + market context to make it read well locally. Not a literal translation — a local marketer's version. |\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/TRANSLATION_PHILOSOPHY.md#the-complexity-spectrum", "metadata": {"genre": "translation", "source_file": "TRANSLATION_PHILOSOPHY.md", "section_anchor": "the-complexity-spectrum", "feature_slug": "translation", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "771d0e9f525fc24d618e3fa2d595f03238c798af7c187a3540bad9c8bf22ef74", "truncated": false}, "is_active": true}, {"id": "a409b461-9671-5b65-8d8f-8413e6e0302f", "feature_slug": "translation", "title": "Tone Calibration", "content": "Each market has a different baseline tone. The market-specific doc specifies where on the spectrum, but here's the universal framework:\n\n| Dimension | Formal end | Casual end | Notes |\n|---|---|---|---|\n| **Formality** | Enterprise Japanese (です/ます, honorifics) | Thai B2B/SME (direct, conversational, no corporate padding) | Match audience segment, not just market |\n| **Directness** | English (direct, outcome-focused) | Japanese (implications, softer framing) | Cultural communication norms |\n| **Tech confidence** | English/TW (AI is exciting, lean into it) | JP enterprise (AI is risky, pair with control/guardrails) | How the market perceives AI claims |\n| **Urgency** | Specific numbers always (JP: \"最短1ヶ月\") | Vague superlatives never | All markets: precision beats superlatives |\n\n**Thailand (B2B/SME):** Strip overly formal corporate padding and unnatural metaphors. Write like a sharp marketer talking to an operator — not a translated press release. If a literal English→Thai line sounds clever on paper but awkward spoken aloud, rewrite in neutral, natural business Thai.\n\n**Structure fidelity in every market:** A title stays a punchy title; a description stays a concise mechanism explanation. Do not let localization bloat layout or force a redesign. If the target language needs more words, shorten the idea — do not add elements.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/TRANSLATION_PHILOSOPHY.md#tone-calibration", "metadata": {"genre": "translation", "source_file": "TRANSLATION_PHILOSOPHY.md", "section_anchor": "tone-calibration", "feature_slug": "translation", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "7f8bfc8ecea8c83585a254f2c60aa29dc25ad5f4fe4ae2e5eacd0ebf7142e5ff", "truncated": false}, "is_active": true}, {"id": "a5f7bde0-b04c-5550-a314-316747340db3", "feature_slug": "translation", "title": "Translation & Localization — Overview", "content": "**When to use:** Add after genre playbook when output is Thai, JP, TW, or mixed EN/local. Localize-don't-translate, term policy, tone calibration.\n            **Source:** `TRANSLATION_PHILOSOPHY.md`\n            **Genre:** `translation`\n\n**Cross-cutting:** Add after the genre playbook when localizing.\n\n            Translation Philosophy — Universal Principles", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/TRANSLATION_PHILOSOPHY.md", "metadata": {"genre": "translation", "source_file": "TRANSLATION_PHILOSOPHY.md", "section_anchor": "overview", "feature_slug": "translation", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "6063af023db897399cbcd63dd03bce6ac054631b6cfaf16cc4adca2575ebcbf1", "truncated": false}, "is_active": true}]$seed_json$::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
